import { sql } from "drizzle-orm";
import { pgTable, text, timestamp, index, pgEnum, unique, check } from "drizzle-orm/pg-core";
import { user } from "./auth-schema.js";

// All possible states of a connection request.
export const connectionStatusEnum = pgEnum("connection_status", [
  "ignored",
  "interested",
  "accepted",
  "rejected",
]);

export const connectionRequest = pgTable(
  "connectionRequest",
  {
    // Generated by the app when a request is created (matches the text id style of the user table).
    id: text("id").primaryKey().$defaultFn(() => crypto.randomUUID()),
    fromUserId: text("from_user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    toUserId: text("to_user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    status: connectionStatusEnum("status").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [
    // Fast lookups: "requests I sent" / "requests I received".
    index("connection_request_from_user_id_idx").on(table.fromUserId),
    index("connection_request_to_user_id_idx").on(table.toUserId),
    // A user pair can only ever have ONE request (A→B). Re-sends just update status.
    unique("connection_request_from_to_unique").on(table.fromUserId, table.toUserId),
    // Nobody can send a request to themselves.
    check("connection_request_no_self_requests_check", sql`${table.fromUserId} <> ${table.toUserId}`),
  ],
);

export type ConnectionRequest = typeof connectionRequest.$inferSelect;
export type NewConnectionRequest = typeof connectionRequest.$inferInsert;
